import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { ContextPruningTracker } from "./src/core/context-pruning/tracker.ts";
import { recoverablePrune } from "./src/core/context-pruning/recovery.ts";
import type { ToolRecord } from "./src/core/context-pruning/types.ts";

const root = mkdtempSync(join(tmpdir(), "aide-pruning-regression-"));
afterAll(() => rmSync(root, { recursive: true, force: true }));
const output = "検索結果🙂\\n".repeat(500);
const args = { query: "example" };
const full = (callId: string): ToolRecord => ({ callId, toolName: "code_search", args, originalOutput: output, prunedOutput: null, timestamp: 0 });

test("finalized output and retained originals survive history reload with byte accounting", () => {
  const tracker = new ContextPruningTracker(root);
  const emitted: string[] = [];
  for (const id of ["first", "second", "third"]) {
    const result = tracker.process(id, "code_search", args, output, recoverablePrune(root, "session", id, output));
    emitted.push(result.output);
    if (id !== "first") {
      expect(result.output).toContain("callId: first");
      expect(readFileSync(result.recoveryPath!, "utf8")).toBe(output);
      expect(result.bytesSaved).toBe(Buffer.byteLength(output) - Buffer.byteLength(result.output));
    }
  }
  const history = tracker.getHistory();
  expect(history.map(r => r.prunedOutput ?? r.originalOutput)).toEqual(emitted);
  expect(history.every(r => r.originalOutput === output)).toBe(true);
  const bytes = emitted.reduce((n, text) => n + Buffer.byteLength(text), 0);
  expect(tracker.getStats()).toEqual({ totalCalls: 3, prunedCalls: 2, estimatedContextBytes: bytes, totalBytesSaved: 3 * Buffer.byteLength(output) - bytes });
  const reloaded = new ContextPruningTracker(root);
  reloaded.loadHistory(JSON.parse(JSON.stringify(history)));
  expect(reloaded.getStats()).toEqual(tracker.getStats());
  expect(reloaded.process("fourth", "code_search", args, output).output).toContain("callId: first");
});

test("selects the most recent matching full output, skipping shortened entries", () => {
  const tracker = new ContextPruningTracker(root);
  tracker.loadHistory([full("old"), full("recent"), { ...full("short"), prunedOutput: "pointer" }]);
  expect(tracker.process("next", "code_search", args, output).output).toContain("callId: recent");
});

test("eviction emits a fresh baseline when only shortened matches remain", () => {
  const tracker = new ContextPruningTracker(root, 2);
  const run = (id: string) => tracker.process(id, "code_search", args, output);
  expect(run("a").modified).toBe(false);
  expect(run("b").output).toContain("callId: a");
  expect(run("c").output).toContain("callId: a");
  expect(run("d").output).toBe(output);
  expect(run("e").output).toContain("callId: d");
});

test("an emitted pointer is never itself a full-output target", () => {
  const tracker = new ContextPruningTracker(root);
  tracker.loadHistory([{ ...full("short"), prunedOutput: "pointer" }]);
  expect(tracker.process("next", "code_search", args, "pointer").modified).toBe(false);
});

test("recovery rejection records the emitted original as the newest baseline", () => {
  const tracker = new ContextPruningTracker(root);
  tracker.process("a", "code_search", args, output);
  const rejected = tracker.process("b", "code_search", args, output, recoverablePrune(root, "", "b", output));
