  }
  expect(tracker.getHistory().every(r => r.prunedOutput === null)).toBe(true);
  expect(tracker.getStats().prunedCalls).toBe(0);
});

test("different arguments and outputs do not match", () => {
  const tracker = new ContextPruningTracker(root);
  tracker.process("a", "code_search", args, output);
  expect(tracker.process("b", "code_search", { query: "different" }, output).modified).toBe(false);
  expect(tracker.process("c", "code_search", args, output + "changed").modified).toBe(false);
  expect(tracker.process("d", "code_search", args, output).output).toContain("callId: a");
});

test("side-effecting tools are unchanged on repeat", () => {
  for (const tool of ["Bash", "Write", "Edit", "memory_add", "task_update"]) {
    const tracker = new ContextPruningTracker(root);
    tracker.process("a", tool, args, output);
    expect(tracker.process("b", tool, args, output)).toEqual({ output, modified: false, bytesSaved: 0 });
  }
});
